package com.payguard.payment.controller; import com.payguard.payment.domain.Transaction; import com.payguard.payment.service.PaymentService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/v1/payments") public class PaymentController { private final PaymentService service; public PaymentController(PaymentService service){this.service=service;} public record Create(@Min(1) long amountMinor,@NotBlank @Pattern(regexp="[A-Za-z]{3}") String currency){} @PostMapping public ResponseEntity<?> create(@Valid @RequestBody Create request,@AuthenticationPrincipal Jwt jwt){return ResponseEntity.status(HttpStatus.CREATED).body(view(service.create(merchant(jwt),request.amountMinor(),request.currency().toUpperCase())));}@GetMapping("/{id}") public Map<String,Object> get(@PathVariable String id,@AuthenticationPrincipal Jwt jwt){return view(service.get(id,merchant(jwt)));} private String merchant(Jwt jwt){String id=jwt.getClaimAsString("merchant_id");if(id==null)throw new org.springframework.security.access.AccessDeniedException("merchant_id claim is required");return id;} private Map<String,Object> view(Transaction t){Map<String,Object> v=new LinkedHashMap<>();v.put("transaction_id",t.getTransactionId());v.put("status",t.getStatus());v.put("fraud_score",t.getFraudScore());v.put("fraud_decision",t.getFraudDecision());return v;} }
